func resourceVertexAIEndpointDeployedModelDelete(d *schema.ResourceData, meta interface{}) error {
	if d.Get("deletion_policy").(string) == "PREVENT" {
		return fmt.Errorf("cannot destroy VertexAIEndpointDeployedModel without setting deletion_policy=\"DELETE\" and running `terraform apply`")
	}
	if d.Get("deletion_policy").(string) == "ABANDON" {
		log.Printf("[DEBUG] deletion_policy set to \"ABANDON\", removing EndpointDeployedModel %q from Terraform state without deletion", d.Id())
		return nil
	}
	var project string
	config := meta.(*transport_tpg.Config)
	userAgent, err := tpgresource.GenerateUserAgentString(d, config.UserAgent)
	if err != nil {
		return err
	}

	billingProject := ""

	url, err := tpgresource.ReplaceVars(d, config, transport_tpg.BaseUrl(Product, config)+"{{endpoint}}:undeployModel")
	if err != nil {
		return err
	}
	if strings.Contains(url, "{{region}}") {
		return fmt.Errorf("failed to qualify endpoint for a resource with a regionalized endpoint %s", url)
	}

	var obj map[string]interface{}
	if parts := regexp.MustCompile(`projects\/([^\/]+)\/`).FindStringSubmatch(url); parts != nil {
		billingProject = parts[1]
	}

	// err == nil indicates that the billing_project value was found
	if bp, err := tpgresource.GetBillingProject(d, config); err == nil {
		billingProject = bp
	}

	headers := make(http.Header)
	project = billingProject

	endpointURL, err := tpgresource.ReplaceVars(d, config, transport_tpg.BaseUrl(Product, config)+"{{endpoint}}")
	if err != nil {
		return err
	}
	endpoint, err := transport_tpg.SendRequest(transport_tpg.SendRequestOptions{
		Config: config, Method: "GET", Project: billingProject, RawURL: endpointURL,
		UserAgent: userAgent, Timeout: d.Timeout(schema.TimeoutDelete),
	})
	if err != nil {
		return transport_tpg.HandleNotFoundError(err, d, "EndpointDeployedModel")
	}

	deployedModelID := d.Get("deployed_model_id").(string)
	receivesTraffic, otherReceivesTraffic := false, false
	percents := map[string]int{}
	if rawSplit := endpoint["trafficSplit"]; rawSplit != nil {
		split, ok := rawSplit.(map[string]interface{})
		if !ok {
			return fmt.Errorf("Invalid traffic split on endpoint %q: expected an object, got %T", d.Get("endpoint"), rawSplit)
		}
		for modelID, rawPercent := range split {
			percent, ok := rawPercent.(float64)
			if !ok || percent < 0 || percent > 100 || float64(int(percent)) != percent {
				return fmt.Errorf("Invalid traffic percentage for deployed model %q on endpoint %q: %v", modelID, d.Get("endpoint"), rawPercent)
			}
			percents[modelID] = int(percent)
			if percent > 0 {
				if modelID == deployedModelID {
					receivesTraffic = true
				} else {
					otherReceivesTraffic = true
				}
			}
		}
	}

	var redistributedSplit map[string]interface{}
	if receivesTraffic && otherReceivesTraffic {
		// Hand this model's share to the remaining recipients in proportion to
		// their current share, using largest remainders so the split stays whole.
		total, othersTotal := 0, 0
		var recipients []string
		for modelID, percent := range percents {
			total += percent
			if modelID != deployedModelID && percent > 0 {
				othersTotal += percent
				recipients = append(recipients, modelID)
			}
		}
		sort.Strings(recipients)
		newSplit, remainders, assigned := map[string]int{}, map[string]int{}, 0
		for modelID, percent := range percents {
			if modelID != deployedModelID {
				newSplit[modelID] = percent
			}
		}
		for _, modelID := range recipients {
			scaled := percents[modelID] * total
			newSplit[modelID] = scaled / othersTotal
			remainders[modelID] = scaled % othersTotal
			assigned += newSplit[modelID]
		}
		sort.SliceStable(recipients, func(i, j int) bool { return remainders[recipients[i]] > remainders[recipients[j]] })
		for i := 0; assigned < total; i++ {
			newSplit[recipients[i]]++
			assigned++
		}
		redistributedSplit = map[string]interface{}{}
		for modelID, percent := range newSplit {
			redistributedSplit[modelID] = percent
		}
		log.Printf("[DEBUG] Redistributing traffic of deployed model %q on endpoint %q: %v", deployedModelID, d.Get("endpoint"), newSplit)
	} else if receivesTraffic {
		etag, ok := endpoint["etag"].(string)
		if !ok || etag == "" {
			return fmt.Errorf("Cannot safely clear traffic on endpoint %q before undeploying model %q: endpoint response has no etag", d.Get("endpoint"), d.Get("deployed_model_id"))
		}
		_, err = transport_tpg.SendRequest(transport_tpg.SendRequestOptions{
			Config: config, Method: "PATCH", Project: billingProject, RawURL: endpointURL + "?updateMask=trafficSplit",
			UserAgent: userAgent, Timeout: d.Timeout(schema.TimeoutDelete),
			Body: map[string]interface{}{"trafficSplit": map[string]interface{}{}, "etag": etag},
		})
		if err != nil {
			return fmt.Errorf("Error clearing endpoint traffic before undeploying model %q; verify the traffic split and retry: %w", d.Get("deployed_model_id"), err)
		}
	}

	obj = map[string]interface{}{
		"deployedModelId": deployedModelID,
	}
	if redistributedSplit != nil {
		obj["trafficSplit"] = redistributedSplit
	}

	log.Printf("[DEBUG] Deleting EndpointDeployedModel %q", d.Id())
	res, err := transport_tpg.SendRequest(transport_tpg.SendRequestOptions{
		Config:    config,
		Method:    "POST",
		Project:   billingProject,
		RawURL:    url,
		UserAgent: userAgent,
		Body:      obj,
		Timeout:   d.Timeout(schema.TimeoutDelete),
		Headers:   headers,
	})
	if err != nil {
		return transport_tpg.HandleNotFoundError(err, d, "EndpointDeployedModel")
	}

	// Derive location for use in REP endpoints
	endpointLocation := tpgresource.LocationFromId(d.Id())
	err = VertexAIOperationWaitTime(
		config, res, project, endpointLocation, "Deleting EndpointDeployedModel", userAgent,
		d.Timeout(schema.TimeoutDelete))

	if err != nil {
		return err
	}

	log.Printf("[DEBUG] Finished deleting EndpointDeployedModel %q: %#v", d.Id(), res)
	return nil
}

func resourceVertexAIEndpointDeployedModelImport(d *schema.ResourceData, meta interface{}) ([]*schema.ResourceData, error) {
	config := meta.(*transport_tpg.Config)

	if err := tpgresource.ParseImportId([]string{
		"(?P<endpoint>.+)/deployedModels/(?P<deployed_model_id>[^/]+)",
	}, d, config); err != nil {
		return nil, err
	}

	endpointRe := regexp.MustCompile(`^projects/(?P<project>[^/]+)/locations/(?P<region>[^/]+)/endpoints/[^/]+$`)
	if m := endpointRe.FindStringSubmatch(d.Get("endpoint").(string)); m != nil {
		if err := d.Set("region", m[2]); err != nil {
			return nil, fmt.Errorf("Error setting region: %s", err)
		}
	}

	id, err := tpgresource.ReplaceVars(d, config, "{{endpoint}}/deployedModels/{{deployed_model_id}}")
	if err != nil {
		return nil, fmt.Errorf("Error constructing id: %s", err)
	}
	d.SetId(id)

	return []*schema.ResourceData{d}, nil
}

