func resourceVertexAIEndpointDeployedModelEncoder(d *schema.ResourceData, meta interface{}, obj map[string]interface{}) (map[string]interface{}, error) {
	if d.Get("region").(string) == "" {
		endpoint := d.Get("endpoint").(string)
		region := tpgresource.GetRegionFromRegionalSelfLink(endpoint)
		if region == "" || region == endpoint {
			return nil, fmt.Errorf("Cannot determine region from endpoint %q", endpoint)
		}
		if err := d.Set("region", region); err != nil {
			return nil, fmt.Errorf("Error setting region: %s", err)
		}
	}

	if _, ok := d.GetOk("dedicated_resources.0.machine_spec"); ok {
		if resources, ok := obj["dedicatedResources"].(map[string]interface{}); ok {
			if _, exists := resources["machineSpec"]; !exists {
				resources["machineSpec"] = map[string]interface{}{}
			}
		}
	}

	deployedModel := obj
	deployedModel["id"] = d.Get("deployed_model_id")
	delete(deployedModel, "deployedModelId")
	delete(deployedModel, "endpoint")
	delete(deployedModel, "region")
	return map[string]interface{}{"deployedModel": deployedModel}, nil
}

func resourceVertexAIEndpointDeployedModelUpdateEncoder(d *schema.ResourceData, meta interface{}, obj map[string]interface{}) (map[string]interface{}, error) {
	deployedModel := map[string]interface{}{"id": d.Get("deployed_model_id")}
	updateMask := []string{}
	for _, resources := range []struct {
		terraformName string
		apiName       string
		fields        []struct{ terraformName, apiName string }
	}{
		{"dedicated_resources", "dedicatedResources", []struct{ terraformName, apiName string }{
			{"min_replica_count", "minReplicaCount"},
			{"max_replica_count", "maxReplicaCount"},
			{"required_replica_count", "requiredReplicaCount"},
		}},
	} {
		changed := map[string]interface{}{}
		for _, field := range resources.fields {
			path := resources.terraformName + ".0." + field.terraformName
			if d.HasChange(path) {
				changed[field.apiName] = d.Get(path)
				updateMask = append(updateMask, resources.apiName+"."+field.apiName)
			}
		}
		if resources.terraformName == "dedicated_resources" && d.HasChange("dedicated_resources.0.autoscaling_metric_specs") {
			metrics, err := expandVertexAIEndpointDeployedModelDedicatedResourcesAutoscalingMetricSpecs(
				d.Get("dedicated_resources.0.autoscaling_metric_specs"), d, meta.(*transport_tpg.Config))
			if err != nil {
				return nil, err
			}
			changed["autoscalingMetricSpecs"] = metrics
			updateMask = append(updateMask, "dedicatedResources.autoscalingMetricSpecs")
		}
		if len(changed) != 0 {
			deployedModel[resources.apiName] = changed
		}
	}
	if d.HasChange("enable_container_logging") {
		// v1beta1 mutateDeployedModel only accepts enableContainerLogging.
		deployedModel["enableContainerLogging"] = d.Get("enable_container_logging")
		updateMask = append(updateMask, "enableContainerLogging")
	}
	return map[string]interface{}{
		"deployedModel": deployedModel,
		"updateMask":    strings.Join(updateMask, ","),
	}, nil
}

func resourceVertexAIEndpointDeployedModelDecoder(d *schema.ResourceData, meta interface{}, res map[string]interface{}) (map[string]interface{}, error) {
	if d.Get("region").(string) == "" {
		endpointRe := regexp.MustCompile(`^projects/[^/]+/locations/(?P<region>[^/]+)/endpoints/[^/]+$`)
		if m := endpointRe.FindStringSubmatch(d.Get("endpoint").(string)); m != nil {
			if err := d.Set("region", m[1]); err != nil {
				return nil, fmt.Errorf("Error setting region: %s", err)
			}
		}
	}

	rawDeployedModels, ok := res["deployedModels"]
	if !ok || rawDeployedModels == nil {
		return nil, nil
	}
	deployedModels, ok := rawDeployedModels.([]interface{})
	if !ok {
		return nil, fmt.Errorf("expected deployedModels to be an array, got %T", rawDeployedModels)
	}
	for _, rawDeployedModel := range deployedModels {
		deployedModel, ok := rawDeployedModel.(map[string]interface{})
		if !ok {
			return nil, fmt.Errorf("expected deployed model to be an object, got %T", rawDeployedModel)
		}
		if deployedModel["id"] == d.Get("deployed_model_id") {
			deployedModel["endpoint"] = d.Get("endpoint")
			deployedModel["deployedModelId"] = d.Get("deployed_model_id")
			return deployedModel, nil
		}
	}
	return nil, nil
}

